from pathlib import Path
seed=Path('/mnt/data/friday-list-v6/seed.js').read_text()
html=r'''<!doctype html><html lang="uk"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Friday List · Wishlist</title><style>
:root{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#302a28;background:#faf8f6}*{box-sizing:border-box}body{margin:0}button,input,select{font:inherit}button{cursor:pointer;border:0}a{color:inherit}header{position:sticky;top:0;z-index:10;background:#faf8f6f5;border-bottom:1px solid #eee6e2;backdrop-filter:blur(12px)}.wrap{max-width:1140px;margin:auto;padding:0 24px}.top{display:flex;align-items:center;justify-content:space-between;padding-top:17px}.brand{font-size:26px;font-weight:780;letter-spacing:-1.2px}.spark{color:#bb7e89}.sub{font-size:12px;color:#93847e;margin-top:2px}.topright{font-size:11px;letter-spacing:.12em;color:#8d8079}.add{display:flex;gap:8px;padding:15px 0}.add input{flex:1;min-width:0;border:1px solid #e7dad4;border-radius:12px;background:#fff;padding:13px 15px;outline:none}.add input:focus{border-color:#bd8e93}.primary{background:#322826;color:white;border-radius:11px;padding:12px 19px;font-weight:600}.main{padding-top:26px;padding-bottom:60px}.intro{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;margin-bottom:20px}.intro h1{font-size:25px;letter-spacing:-.8px;margin:0 0 6px}.hint{color:#92847d;font-size:13px}.summary{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:22px}.metric{background:white;border:1px solid #eee5e0;border-radius:14px;padding:13px 18px;min-width:145px}.metric b{font-size:24px;display:block;margin-top:4px}.metric small{color:#91827c}.controls{display:flex;align-items:center;gap:10px;justify-content:space-between;margin-bottom:18px;flex-wrap:wrap}.tabs{display:flex;gap:6px;background:#eee8e5;padding:4px;border-radius:12px}.tabs button{background:transparent;border-radius:9px;padding:10px 13px;color:#675b57}.tabs button.active{background:#fff;box-shadow:0 1px 4px #0000000b;color:#2f2725;font-weight:650}.filters{display:flex;align-items:center;gap:8px}.filters select,.filters button{border:1px solid #e8ded9;background:white;border-radius:10px;padding:10px;color:#4a3b36}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.card{border:1px solid #eae1dc;border-radius:17px;background:white;overflow:hidden;display:flex;min-height:220px}.photo{width:39%;background:#f2eeeb;display:flex;align-items:center;justify-content:center;text-align:center;color:#9d8f88;font-size:12px;padding:12px;flex-shrink:0}.photo img{width:100%;height:100%;max-height:290px;object-fit:contain}.info{flex:1;min-width:0;padding:17px;display:flex;flex-direction:column;gap:9px}.name{font-size:16px;font-weight:720;line-height:1.35}.detail{font-size:12px;color:#877b75;line-height:1.5}.price{font-size:19px;font-weight:750;letter-spacing:-.4px}.unknown{font-size:14px;font-weight:600;color:#8b7d76}.status{font-size:12px;color:#9b8c84}.status.yes{color:#227d55}.status.no{color:#ba5656}.offers{display:flex;gap:5px;flex-wrap:wrap}.offer{font-size:11px;border-radius:7px;padding:7px 9px;background:#f1ece9;color:#5f524c}.offer.active{background:#352b28;color:white}.foot{display:flex;gap:7px;flex-wrap:wrap;margin-top:auto}.foot a,.foot button{border-radius:8px;padding:8px 10px;font-size:12px;text-decoration:none;background:#f1ebe8;color:#3e322f}.foot a{background:#332927;color:white}.purchased{opacity:.78}.empty{padding:45px;border:1px dashed #e4d9d3;border-radius:16px;color:#92847e;text-align:center;grid-column:1/-1}.settings{margin-top:28px;border-top:1px solid #e9dfda;padding-top:18px}.settings summary{cursor:pointer;color:#877970;font-size:13px}.settings button,.settings label{display:inline-block;background:#eee7e3;border:0;border-radius:9px;padding:9px 12px;font-size:12px;color:#443834;cursor:pointer;margin:10px 7px 0 0}.note{font-size:12px;color:#94857e;line-height:1.55;margin-top:15px}.toast{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:#332927;color:white;padding:12px 18px;border-radius:10px;z-index:20;max-width:90%;display:none}.dialog{border:1px solid #e8dcd5;border-radius:18px;padding:25px;width:min(470px,94vw);box-shadow:0 25px 70px #30231c33}.dialog::backdrop{background:#2b201b77}.dialog h2{margin:0 0 16px}.field{display:block;font-size:12px;color:#72645e;margin:12px 0}.field input,.field select{display:block;width:100%;margin-top:5px;padding:10px;border:1px solid #e5d8d1;border-radius:9px;background:white}.dialogactions{display:flex;gap:8px;justify-content:flex-end;margin-top:18px}.dialogactions button{padding:11px 16px;border-radius:9px;background:#eee7e3}.dialogactions button.primary{background:#322826;color:white}.strike{text-decoration:line-through;color:#a1958e;font-size:12px}.green{color:#227d55;font-size:12px}.count{font-size:12px;color:#93847d}@media(max-width:760px){.wrap{padding:0 14px}.top{padding-top:13px}.brand{font-size:23px}.topright{font-size:9px}.sub{display:none}.add{padding:12px 0}.add input{font-size:14px}.add button{padding:11px 13px}.main{padding-top:22px}.intro h1{font-size:22px}.summary{gap:7px}.metric{min-width:0;flex:1;padding:11px}.metric b{font-size:20px}.metric small{font-size:11px}.cards{grid-template-columns:1fr}.card{min-height:195px}.photo{width:36%}.info{padding:13px;gap:8px}.name{font-size:15px}.controls{align-items:stretch}.filters{width:100%}.filters select{flex:1}.foot a,.foot button{padding:8px}.intro{align-items:center}}
</style></head><body><header><div class="wrap"><div class="top"><div><div class="brand">Friday List <span class="spark">✳</span></div><div class="sub">Твій персональний список покупок</div></div><div class="topright">BLACK FRIDAY 2026</div></div><form class="add" id="addForm"><input id="url" type="url" placeholder="Встав посилання на товар…" required aria-label="Посилання на товар"><button class="primary">+ Додати</button></form></div></header><main class="wrap main"><div class="intro"><div><h1>Мій wishlist</h1><div class="hint">Відстежуй бажане. Купуй у правильний момент.</div></div><span class="count" id="visibleCount"></span></div><div class="summary"><div class="metric"><small>Хочу купити</small><b id="total">0</b></div><div class="metric"><small>Зі знижкою</small><b id="discounted">0</b></div><div class="metric"><small>Придбала</small><b id="bought">0</b></div></div><div class="controls"><div class="tabs"><button id="wishlistTab" class="active" type="button">Хочу купити</button><button id="purchasedTab" type="button">Придбала</button></div><div class="filters"><select id="filter" aria-label="Фільтр товарів"><option value="all">Усі товари</option><option value="discount">Зі знижкою</option><option value="stock">У наявності</option><option value="unknown">Без ціни</option></select><button id="refresh" title="Потрібен локальний сервер Netlify">↻ Перевірити</button></div></div><section class="cards" id="cards"></section><details class="settings"><summary>Налаштування та дані</summary><div><button id="restore">Додати відсутні стартові товари</button><button id="export">Експорт JSON</button><label>Імпорт JSON <input id="import" type="file" accept="application/json" hidden></label></div><p class="note">Дані зберігаються тільки в цьому браузері. Ціни, наявність та оригінальні фотографії ще не перевіряються автоматично в режимі локального HTML. Для цього потрібен сервер. Не підставляємо випадкові фотографії або неперевірені ціни.</p></details></main><dialog class="dialog" id="editor"><form id="editForm"><h2>Редагувати товар</h2><input id="editId" type="hidden"><label class="field">Назва<input id="editName" required></label><label class="field">Характеристики<input id="editDetails"></label><label class="field">Ціна<input id="editPrice" type="number" min="0" step="0.01" placeholder="Не перевірено"></label><label class="field">Валюта<select id="editCurrency"><option>UAH</option><option>PLN</option><option>EUR</option><option>AUD</option><option>USD</option></select></label><label class="field">Наявність<select id="editStock"><option value="unknown">Не перевірено</option><option value="yes">У наявності</option><option value="no">Немає в наявності</option></select></label><label class="field">URL оригінального фото<input id="editImage" type="url" placeholder="Тільки з точної сторінки товару"></label><div class="dialogactions"><button type="button" id="cancelEdit">Скасувати</button><button class="primary">Зберегти</button></div></form></dialog><div id="toast" class="toast" role="status"></div><script>
__SEED__
const KEY='friday-list-v6';const LEGACY='friday-list-v5-repaired';const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const initial=()=>seed.map((s,i)=>({id:i+1,name:s[0],url:s[1],currency:s[2],details:s[3],price:null,previous:null,stock:'unknown',image:'',checked:null,history:[],purchased:false,purchasedAt:null}));let data;try{const saved=localStorage.getItem(KEY);const legacy=localStorage.getItem(LEGACY);data=saved!==null?JSON.parse(saved):legacy!==null?JSON.parse(legacy):initial();if(!Array.isArray(data))data=initial()}catch{data=initial()}data=data.filter(x=>x&&x.url).map(x=>({...x,purchased:!!x.purchased,history:Array.isArray(x.history)?x.history:[],stock:x.stock||'unknown'}));let activeTab='wishlist';const selected={};const save=()=>{localStorage.setItem(KEY,JSON.stringify(data));render()};const showToast=msg=>{const t=$('toast');t.textContent=msg;t.style.display='block';clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.style.display='none',2800)};const isZara=x=>/zarahome\.com/.test(x.url)&&/42489747/.test(x.url);const region=x=>/zarahome\.com\/ua\//.test(x.url)?'🇺🇦 Україна':/zarahome\.com\/pl\//.test(x.url)?'🇵🇱 Польща':'🇪🇸 Іспанія';const fmt=x=>x.price==null?'Ціна не перевірена':new Intl.NumberFormat('uk-UA',{style:'currency',currency:x.currency||'UAH'}).format(x.price);const discount=x=>x.price!=null&&x.previous>0&&x.price<x.previous;function groups(){const out=[];const z=data.filter(isZara);for(const x of data){if(isZara(x)){if(out.some(g=>g.key==='zara'))continue;out.push({key:'zara',items:z})}else out.push({key:String(x.id),items:[x]})}return out}function render(){const purchased=activeTab==='purchased';$('wishlistTab').classList.toggle('active',!purchased);$('purchasedTab').classList.toggle('active',purchased);$('total').textContent=groups().filter(g=>g.items.some(x=>!x.purchased)).length;$('bought').textContent=groups().filter(g=>g.items.every(x=>x.purchased)).length;$('discounted').textContent=groups().filter(g=>g.items.some(x=>!x.purchased&&discount(x))).length;let displayed=groups().filter(g=>purchased?g.items.every(x=>x.purchased):g.items.some(x=>!x.purchased));const f=$('filter').value;displayed=displayed.filter(g=>f==='all'||f==='discount'&&g.items.some(discount)||f==='stock'&&g.items.some(x=>x.stock==='yes')||f==='unknown'&&g.items.some(x=>x.price==null));$('visibleCount').textContent=displayed.length+' товарів';$('cards').innerHTML=displayed.length?displayed.map(g=>{const candidates=g.items.filter(x=>x.purchased===purchased);const pool=candidates.length?candidates:g.items;let x=pool.find(x=>String(x.id)===String(selected[g.key]))||pool[0];selected[g.key]=x.id;const multi=g.items.length>1;const img=x.image&&/^https:\/\//.test(x.image)?`<img src="${esc(x.image)}" alt="${esc(x.name)}" onerror="this.parentElement.textContent='Оригінальне фото недоступне'">`:'Оригінальне фото ще не додане';return `<article class="card ${purchased?'purchased':''}"><div class="photo">${img}</div><div class="info"><div class="name">${multi?'Zara Home · Gingerbread set':esc(x.name)}</div><div class="detail">${multi?'Набір із 3 · Артикул 42489747':esc(x.details)}</div>${multi?`<div class="offers">${g.items.map(o=>`<button class="offer ${o.id===x.id?'active':''}" data-offer="${esc(g.key)}" data-id="${o.id}">${region(o)}</button>`).join('')}</div>`:''}<div class="price ${x.price==null?'unknown':''}">${esc(fmt(x))}</div>${discount(x)?`<div class="green">↓ ${Math.round((x.previous-x.price)/x.previous*100)}% від попередньої ціни</div>`:''}<div class="status ${x.stock}">${x.stock==='yes'?'● У наявності':x.stock==='no'?'● Немає в наявності':'● Наявність не перевірена'}</div><div class="foot"><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Магазин ↗</a><button data-buy="${esc(g.key)}">${purchased?'↶ Повернути':'✓ Придбала'}</button><button data-edit="${x.id}">Редагувати</button><button data-remove="${x.id}" aria-label="Видалити">×</button></div></div></article>`}).join(''):'<div class="empty">Тут поки немає товарів</div>'}function normalizeUrl(u){try{const x=new URL(u);x.hash='';return x.href}catch{return u}}$('cards').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.offer){selected[b.dataset.offer]=Number(b.dataset.id);render()}else if(b.dataset.buy){const g=groups().find(g=>g.key===b.dataset.buy);if(!g)return;const to=!g.items.every(x=>x.purchased);g.items.forEach(x=>{x.purchased=to;x.purchasedAt=to?new Date().toLocaleDateString('uk-UA'):null});save();showToast(to?'Перенесено в «Придбала»':'Повернуто до wishlist')}else if(b.dataset.edit){const x=data.find(x=>x.id===Number(b.dataset.edit));if(!x)return;$('editId').value=x.id;$('editName').value=x.name;$('editDetails').value=x.details||'';$('editPrice').value=x.price??'';$('editCurrency').value=x.currency||'UAH';$('editStock').value=x.stock||'unknown';$('editImage').value=x.image||'';$('editor').showModal()}else if(b.dataset.remove){const id=Number(b.dataset.remove);if(confirm('Видалити це посилання з каталогу?')){data=data.filter(x=>x.id!==id);save()}}});$('cancelEdit').onclick=()=>$('editor').close();$('editForm').onsubmit=e=>{e.preventDefault();const x=data.find(x=>x.id===Number($('editId').value));if(!x)return;const p=$('editPrice').value.trim();const price=p===''?null:Number(p);if(price!==null&&(!Number.isFinite(price)||price<0))return;const image=$('editImage').value.trim();if(image&&!/^https:\/\//.test(image)){showToast('Фото має бути HTTPS-посиланням');return}if(price!=null&&(price!==x.price||!x.history.length)){if(x.price!=null)x.previous=x.price;x.history.push({date:new Date().toLocaleString('uk-UA'),price})}Object.assign(x,{name:$('editName').value.trim(),details:$('editDetails').value.trim(),price,currency:$('editCurrency').value,stock:$('editStock').value,image,checked:new Date().toLocaleString('uk-UA')});$('editor').close();save()};$('addForm').onsubmit=e=>{e.preventDefault();const u=normalizeUrl($('url').value.trim());if(data.some(x=>normalizeUrl(x.url)===u)){showToast('Це посилання вже є в каталозі');return}const host=new URL(u).hostname.replace(/^www\./,'');data.unshift({id:Date.now(),name:host+' · новий товар',url:u,currency:'UAH',details:'Характеристики ще не заповнені',price:null,previous:null,stock:'unknown',image:'',history:[],purchased:false,purchasedAt:null});$('url').value='';activeTab='wishlist';$('filter').value='all';save();showToast('Посилання додано')};$('wishlistTab').onclick=()=>{activeTab='wishlist';render()};$('purchasedTab').onclick=()=>{activeTab='purchased';render()};$('filter').onchange=render;$('refresh').onclick=()=>showToast('Для перевірки магазинів потрібен локальний сервер Netlify. HTML-файл не може зчитати ціни напряму.');$('restore').onclick=()=>{const existing=new Set(data.map(x=>normalizeUrl(x.url)));const missing=initial().filter(x=>!existing.has(normalizeUrl(x.url)));data.push(...missing);activeTab='wishlist';$('filter').value='all';save();showToast('Додано '+missing.length+' відсутніх посилань')};$('export').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='friday-list-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const imported=JSON.parse(await file.text());if(!Array.isArray(imported)||!imported.every(x=>x&&typeof x.url==='string'))throw Error();if(confirm('Замінити поточний каталог імпортованим?')){data=imported;save();showToast('Каталог імпортовано')}}catch{showToast('Некоректний JSON-файл')}e.target.value=''};save();
</script></body></html>'''
Path('/mnt/data/friday-list-v6/index.html').write_text(html.replace('__SEED__',seed))
